class Solution:
    def getSum(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        self.ans = 0
        def dfs(i, last, cur, started):
            if i == n:
                return
            dfs(i + 1, last, cur, started)
            v = nums[i]
            if not started or v == last + 1 or v == last - 1:
                self.ans = (self.ans + cur + v) % MOD
                dfs(i + 1, v, cur + v, True)
        dfs(0, 0, 0, False)
        return self.ans

