class Solution {
public:
    int MOD = 1'000'000'007;
    long long ans = 0;
    void dfs(vector<int>& nums, int i, long long last, long long cur, bool started) {
        int n = nums.size();
        if (i == n) return;
        dfs(nums, i + 1, last, cur, started);
        long long v = nums[i];
        if (!started || v == last + 1 || v == last - 1) {
            ans = (ans + cur + v) % MOD;
            dfs(nums, i + 1, v, cur + v, true);
        }
    }
    int getSum(vector<int>& nums) {
        dfs(nums, 0, 0, 0, false);
        return (int)ans;
    }
};

