    int getSum(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        unordered_map<long long, long long> cntU, sumU, cntD, sumD;
        long long ans = 0;
        for (long long v : nums) {
            long long cu = (cntU[v - 1] + 1) % MOD;
            long long su = (sumU[v - 1] + v * cu) % MOD;
            long long cd = (cntD[v + 1] + 1) % MOD;
            long long sd = (sumD[v + 1] + v * cd) % MOD;
            ans = (ans + su + sd) % MOD;
            cntU[v] = (cntU[v] + cu) % MOD;
            sumU[v] = (sumU[v] + su) % MOD;
            cntD[v] = (cntD[v] + cd) % MOD;
            sumD[v] = (sumD[v] + sd) % MOD;
        }
        return (int)ans;
