class Solution {
    public int getSum(int[] nums) {
        final long MOD = 1_000_000_007L;
        Map<Long, Long> cntU = new HashMap<>(), sumU = new HashMap<>();
        Map<Long, Long> cntD = new HashMap<>(), sumD = new HashMap<>();
        long ans = 0;
        for (long v : nums) {
            long cu = (cntU.getOrDefault(v - 1, 0L) + 1) % MOD;
            long su = (sumU.getOrDefault(v - 1, 0L) + v * cu) % MOD;
            long cd = (cntD.getOrDefault(v + 1, 0L) + 1) % MOD;
            long sd = (sumD.getOrDefault(v + 1, 0L) + v * cd) % MOD;
            ans = (ans + su + sd) % MOD;
            cntU.merge(v, cu, Long::sum); cntU.put(v, cntU.get(v) % MOD);
            sumU.merge(v, su, Long::sum); sumU.put(v, sumU.get(v) % MOD);
            cntD.merge(v, cd, Long::sum); cntD.put(v, cntD.get(v) % MOD);
            sumD.merge(v, sd, Long::sum); sumD.put(v, sumD.get(v) % MOD);
        }
        return (int) ans;
    }
}

