        const sd = (g(sumD, v + 1) + v * cd) % MOD;
        ans = (ans + su + sd) % MOD;
        cntU.set(v, (g(cntU, v) + cu) % MOD);
        sumU.set(v, (g(sumU, v) + su) % MOD);
        cntD.set(v, (g(cntD, v) + cd) % MOD);
        sumD.set(v, (g(sumD, v) + sd) % MOD);
    }
    return ans;
};
